export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const BASE_PREMIUM_PER_COMPONENT = 25;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function isComponent(item: QuoteItem): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function mainItemsOf(items: QuoteItem[]): QuoteItem[] {
  return items.filter((item) => !isComponent(item));
}

function mainItemBasePremiumOf(mainItem: QuoteItem): number {
  return MAIN_ITEM_BASE_PREMIUMS[mainItem.type];
}

function mainItemsBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + mainItemBasePremiumOf(mainItem), 0);
}

function alikenessOf(component: QuoteItem): string {
  return component.type;
}

function alikeComponentCountsOf(items: QuoteItem[]): number[] {
  const countsByAlikeness = new Map<string, number>();
  for (const alikeness of items.filter(isComponent).map(alikenessOf)) {
    countsByAlikeness.set(alikeness, (countsByAlikeness.get(alikeness) ?? 0) + 1);
  }
  return [...countsByAlikeness.values()];
}

function isBuildingBlock(alikeComponentCount: number): boolean {
  return alikeComponentCount === BLOCK_SIZE;
}

function alikeComponentsBasePremiumOf(count: number): number {
  return isBuildingBlock(count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUM_PER_COMPONENT;
}

function componentsBasePremiumOf(items: QuoteItem[]): number {
  return alikeComponentCountsOf(items).reduce((sum, count) => sum + alikeComponentsBasePremiumOf(count), 0);
}

function policyBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsBasePremiumOf(items) + componentsBasePremiumOf(items);
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function firstInsuranceSurchargeOn(policyBasePremium: number): number {
  return percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
}

function premiumRoundedInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function isHighlyEnchanted(mainItem: QuoteItem): boolean {
  return (mainItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
}

function riskSurchargePercentOf(mainItem: QuoteItem): number {
  const curseSurchargePercent = mainItem.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantmentSurchargePercent = isHighlyEnchanted(mainItem) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curseSurchargePercent + highEnchantmentSurchargePercent;
}

function riskSurchargeOn(mainItem: QuoteItem): number {
  return percentOf(mainItemBasePremiumOf(mainItem), riskSurchargePercentOf(mainItem));
}

function riskSurchargesOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + riskSurchargeOn(mainItem), 0);
}

function quote(step: QuoteStep): QuoteResult {
  const policyBasePremium = policyBasePremiumOf(step.items);
  const unroundedPremium =
    policyBasePremium + riskSurchargesOf(step.items) + firstInsuranceSurchargeOn(policyBasePremium) + PROCESSING_FEE;
  return { premium: premiumRoundedInMHPCOsFavor(unroundedPremium) };
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map(quote) };
}
import { describe, expect, it } from "vitest";
import { runScenario, type QuoteItem } from "./claimOffice.js";

const quote = (items: QuoteItem[]) => ({ op: "quote" as const, items });

const premiumFor = (yearsWithMHPCO: number, items: QuoteItem[]) =>
  runScenario({ customer: { yearsWithMHPCO }, steps: [quote(items)] }).results[0];

const alikeComponents = (type: string, count: number): QuoteItem[] => Array.from({ length: count }, () => ({ type }));
const runes = (count: number) => alikeComponents("rune", count);
const moonstones = (count: number) => alikeComponents("moonstone", count);

describe("quote", () => {
  it("empty item list (newcomer) -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor(0, [])).toEqual({ premium: 5 });
  });
  it("newcomer, plain steel sword enchantment 3 -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor(0, [{ type: "sword", material: "steel", enchantment: 3 }])).toEqual({ premium: 115 });
  });
  it("newcomer, plain amulet -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(0, [{ type: "amulet" }])).toEqual({ premium: 71 });
  });
  it("newcomer, plain staff -> 80 + 8 + 5 = 93 G", () => {
    expect(premiumFor(0, [{ type: "staff" }])).toEqual({ premium: 93 });
  });
  it("newcomer, plain potion -> 40 + 4 + 5 = 49 G", () => {
    expect(premiumFor(0, [{ type: "potion" }])).toEqual({ premium: 49 });
  });
  it("newcomer, 2 runes -> base 50 G -> 50 + 5 + 5 = 60 G", () => {
    expect(premiumFor(0, runes(2))).toEqual({ premium: 60 });
  });
  it("newcomer, 1 rune -> 25 + 2.5 + 5 = 32.5 -> rounded up in MHPCO's favor to 33 G", () => {
    expect(premiumFor(0, [{ type: "rune" }])).toEqual({ premium: 33 });
  });
  it("newcomer, 1 moonstone -> 25 + 2.5 + 5 = 32.5 -> 33 G", () => {
    expect(premiumFor(0, [{ type: "moonstone" }])).toEqual({ premium: 33 });
  });
  it("newcomer, 3 runes -> block base 60 G -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(0, runes(3))).toEqual({ premium: 71 });
  });
  it("newcomer, 4 runes -> no block (exactly 3 required), base 100 G -> 115 G", () => {
    expect(premiumFor(0, runes(4))).toEqual({ premium: 115 });
  });
  it("newcomer, 7 runes -> no block, base 175 G -> 197.5 -> rounded up to 198 G", () => {
    expect(premiumFor(0, runes(7))).toEqual({ premium: 198 });
  });
  it("newcomer, 2 runes + 1 moonstone -> no block (different types), base 75 G -> 87.5 -> 88 G", () => {
    expect(premiumFor(0, [...runes(2), ...moonstones(1)])).toEqual({ premium: 88 });
  });
  it("newcomer, 3 runes + 3 moonstones -> two blocks, base 120 G -> 137 G", () => {
    expect(premiumFor(0, [...runes(3), ...moonstones(3)])).toEqual({ premium: 137 });
  });
  it("newcomer, cursed steel sword enchantment 3 -> 100 + 50 curse + 10 first = 160 + 5 = 165 G", () => {
    expect(premiumFor(0, [{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toEqual({ premium: 165 });
  });
  it("newcomer, cursed sword + plain amulet -> curse only on sword: 160 + 50 + 16 + 5 = 231 G", () => {
    expect(premiumFor(0, [{ type: "sword", cursed: true }, { type: "amulet" }])).toEqual({ premium: 231 });
  });
  it("newcomer, sword enchantment exactly 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5 }])).toEqual({ premium: 145 });
  });
  it("newcomer, sword enchantment 4 -> no high-enchantment surcharge: 115 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 4 }])).toEqual({ premium: 115 });
  });
  it("newcomer, cursed sword enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5, cursed: true }])).toEqual({ premium: 195 });
  });
  it("newcomer, cursed sword enchantment 4 -> only curse surcharge: 165 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 4, cursed: true }])).toEqual({ premium: 165 });
  });
  it("newcomer, sword enchantment 5 + plain amulet -> surcharge only on sword: 160 + 30 + 16 + 5 = 211 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5 }, { type: "amulet" }])).toEqual({ premium: 211 });
  });
});

describe("claim", () => {
});

